"""App icon, embedded so it works inside a PyInstaller build without extra data files."""
import base64

from PySide6.QtGui import QIcon, QPixmap

PNG_BASE64 = ""  # filled in by tools/make_icon.py


def app_icon() -> QIcon:
    pm = QPixmap()
    pm.loadFromData(base64.b64decode(PNG_BASE64))
    return QIcon(pm)
